+    if (!buffer) {
+      buffer = { events: [], timer: setTimeout(() => this.flushDeltas(id), 32) };
+      this.deltaBuffers.set(id, buffer);
+    }
+    const last = buffer.events.at(-1);
+    if (last?.id === event.id && last.kind === event.kind) last.text += event.text;
