+    </div>
+    {(item.command || item.kind === 'interaction') && <div className="agent-activity-preview">{(outputPreview(item.text) || (active ? 'Waiting for output…' : '(no output)')).split('\n').map((line, i) => <div key={i} title={line}>{line || '\u00a0'}</div>)}</div>}
