import { describe, expect, it, vi } from 'vitest';
import { AgentChatService } from './agentChatService';
import type { ChatCanvasReader, ChatStore, ChatTools, CodexConnection, CodexMessage } from './ports';
import { reduceChatEvent, type ChatEvent, type ChatSession } from '../../../domain/mapping/agent-chat/agentChat';

class Connection implements CodexConnection {
  calls: { method: string; params: Record<string, unknown> }[] = [];
  replies: { id: string | number; result: unknown }[] = [];
  notify: (message: CodexMessage) => void = () => {};
  exit: (error: string) => void = () => {};
  turn = 0;
  fail = false;
  completeBeforeReply = false;
  async request<T>(method: string, params: Record<string, unknown>): Promise<T> {
    this.calls.push({ method, params });
    if (method === 'thread/start') return { thread: { id: `thread-${this.calls.length}` }, model: 'test-model' } as T;
    if (method === 'turn/start') {
      if (this.fail) throw new Error('turn failed');
      const id = `turn-${++this.turn}`;
      this.notify({ method: 'turn/started', params: { threadId: params.threadId, turn: { id } } });
      if (this.completeBeforeReply) this.notify({ method: 'turn/completed', params: { threadId: params.threadId, turn: { id, status: 'completed' } } });
      return { turn: { id } } as T;
    }
    return {} as T;
  }
  respond(id: string | number, result: unknown) { this.replies.push({ id, result }); }
  reject(id: string | number, result: string) { this.replies.push({ id, result }); }
  subscribe(notify: typeof this.notify, exit: typeof this.exit) { this.notify = notify; this.exit = exit; return () => {}; }
  dispose() {}
}
function fixture(initial: ChatSession[] = [], canvasReader?: ChatCanvasReader, tools?: ChatTools) {
  const connection = new Connection();
  const saved = new Map(initial.map(session => [session.id, structuredClone(session)]));
  const store: ChatStore = { list: async () => [...saved.values()], save: async session => { saved.set(session.id, structuredClone(session)); } };
  const service = new AgentChatService(connection, store, '/workspace', canvasReader, tools);
  return { connection, service, saved, store };
}
const input = (text = 'Hello') => ({ text, requestId: crypto.randomUUID(), model: 'test-model', effort: 'high', sandbox: 'workspace-write' });

describe('Codex agent chat', () => {
  it('defaults to YOLO and carries full access through sends, restart/resume, and Read Canvas', async () => {
    const { service, connection, store } = fixture();
    const session = await service.create({});
    expect(session.settings.sandbox).toBe('danger-full-access');
    expect(connection.calls[0]).toMatchObject({ method: 'thread/start', params: { sandbox: 'danger-full-access', approvalPolicy: 'never' } });
    expect(connection.calls[0].params.developerInstructions).toContain('only create highlights or generate highlight-reference Markdown markers when explicitly instructed');
    await service.send(session.id, { text: 'Hello', requestId: crypto.randomUUID() });
    expect(connection.calls.at(-1)).toMatchObject({ method: 'turn/start', params: { approvalPolicy: 'never', sandboxPolicy: { type: 'dangerFullAccess' } } });
    service.dispose();
    const resumedConnection = new Connection();
    const resumed = new AgentChatService(resumedConnection, store, '/workspace', { shortContextForCanvas: async () => canvasSnapshot() });
    try {
      await resumed.readCanvas(session.id, { canvas: { workspaceInstanceId: 'workspace', documentId: 'doc' }, requestId: crypto.randomUUID() });
      expect(resumedConnection.calls[0]).toMatchObject({ method: 'thread/resume', params: { sandbox: 'danger-full-access', approvalPolicy: 'never' } });
      expect(resumedConnection.calls[0].params.developerInstructions).toBe(connection.calls[0].params.developerInstructions);
      expect(resumedConnection.calls.at(-1)).toMatchObject({ method: 'turn/start', params: { input: [], approvalPolicy: 'never', sandboxPolicy: { type: 'dangerFullAccess' } } });
    } finally { resumed.dispose(); }
  });
  it.each(['read-only', 'workspace-write'] as const)('honors an explicit %s selection instead of YOLO', async sandbox => {
    const { service, connection } = fixture();
    try {
      const session = await service.create({ sandbox });
      expect(connection.calls[0].params).toMatchObject({ sandbox, approvalPolicy: 'on-request' });
      await service.send(session.id, { ...input(), sandbox });
      expect(connection.calls.at(-1)?.params).toMatchObject({ approvalPolicy: 'on-request', sandboxPolicy: { type: sandbox === 'read-only' ? 'readOnly' : 'workspaceWrite' } });
    } finally { service.dispose(); }
  });

  it('registers native edit tools, routes calls with turn-bound canvas context, and returns structured failures', async () => {
    const call = vi.fn(async () => ({ runId: 'edit-1', status: 'generating' }));
    const tools: ChatTools = { definitions: [{ type: 'function', name: 'edit-diagram', description: 'Edit', inputSchema: { type: 'object' } }], call };
    const { service, connection } = fixture([], undefined, tools);
    const session = await service.create({});
    expect(connection.calls[0].params.dynamicTools).toEqual(tools.definitions);
    expect(session.canvasTools).toBe(true);
    const canvas = { workspaceInstanceId: 'workspace', documentId: 'doc' };
    await service.send(session.id, { ...input(), canvas });
    const params = { threadId: session.threadId, turnId: 'turn-1', callId: 'call-1', namespace: null, tool: 'edit-diagram', arguments: { reference: 1, prompt: 'Edit', requestId: 'r' } };
    connection.notify({ method: 'item/tool/call', id: 'native-1', params });
    await expect.poll(() => connection.replies.length).toBe(1);
    expect(call).toHaveBeenCalledWith('edit-diagram', params.arguments, expect.objectContaining({ id: session.id, canvasContext: { canvas, references: [] } }));
    expect(connection.replies[0]).toEqual({ id: 'native-1', result: { success: true, contentItems: [{ type: 'inputText', text: JSON.stringify({ runId: 'edit-1', status: 'generating' }) }] } });
    connection.notify({ method: 'item/tool/call', id: 'native-2', params: { ...params, tool: 'unregistered' } });
    await expect.poll(() => connection.replies.length).toBe(2);
    expect(connection.replies[1].result).toMatchObject({ success: false });
    expect(call).toHaveBeenCalledTimes(1);
    service.dispose();
  });
  it('delivers pinned canvas references with a message and retains them across replay without duplicating a retry', async () => {
    const { service, connection, saved, store } = fixture();
    const session = await service.create({});
    const references = [{ canvas: { workspaceInstanceId: 'workspace', documentId: 'doc' }, canvasName: 'Services', displayNodeId: 'grid:overview',
      reference: { kind: 'diagram', label: 'Service', diagramId: 'diagram-1', revisionId: 'revision-1' }, ascii: 'Service\n\n`-- Child  ' }];
    const request = { ...input('Explain [ref 1]'), references };
    await service.send(session.id, request);
    await service.send(session.id, request);
    const turns = connection.calls.filter(call => call.method === 'turn/start');
    expect(turns).toHaveLength(1);
    const parts = turns[0].params.input as { type: string; text: string }[];
    expect(parts[0].text).toBe('Explain [ref 1]');
    expect(JSON.parse(parts[1].text.slice(parts[1].text.indexOf('\n') + 1))).toEqual([{ ref: 1, ...references[0] }]);
    expect(saved.get(session.id)?.items[0]).toMatchObject({ text: 'Explain [ref 1]', references });
    const restored = new AgentChatService(new Connection(), store, '/workspace');
    expect((await restored.get(session.id)).items[0].references).toEqual(references);
    service.dispose(); restored.dispose();
  });
  it('rejects oversized reference context before starting a turn', async () => {
    const { service, connection } = fixture();
    const session = await service.create({});
    const reference = { canvas: { workspaceInstanceId: 'workspace', documentId: 'doc' }, canvasName: 'Services', displayNodeId: 'grid:overview',
      reference: { kind: 'diagram', label: 'Service', diagramId: 'diagram-1', revisionId: 'revision-1' }, ascii: 'A'.repeat(60_000) };
    await expect(service.send(session.id, { ...input(), references: [reference, reference] })).rejects.toThrow('too large');
    expect(connection.calls.some(call => call.method === 'turn/start')).toBe(false);
    service.dispose();
  });
  const canvasSnapshot = (documentId = 'doc', version = 12) => ({
    apiFormatVersion: 1 as const, shortFormatVersion: 1 as const, view: 'short' as const,
    workspaceInstanceId: 'workspace', documentId, canvasEpoch: 'epoch', version, name: 'Canvas',
    diagrams: [], edges: [], groups: [], selections: [], otherNodes: [], detailsDeferred: []
  });
  const readInput = (documentId = 'doc') => ({ ...input(), canvas: { workspaceInstanceId: 'workspace', documentId } });
  it('delivers complete canvas tool output to the existing thread, with fresh targets and retry deduplication', async () => {
    const snapshot = { ...canvasSnapshot(), name: 'Large canvas ' + 'x'.repeat(130_000) };
    const read = vi.fn<ChatCanvasReader['shortContextForCanvas']>().mockResolvedValue(snapshot);
    const { service, connection, saved } = fixture([], { shortContextForCanvas: read });
    const first = await service.create({}), other = await service.create({});
    const request = readInput();
    await service.readCanvas(first.id, request);
    await service.readCanvas(first.id, request);
    expect(read).toHaveBeenCalledExactlyOnceWith('workspace', 'doc');
    const turn = connection.calls.find(call => call.method === 'turn/start')!;
    expect(turn.params).toMatchObject({ threadId: first.threadId, input: [], toolOutput: { name: 'read_canvas', namespace: null, output: JSON.stringify(snapshot) } });
    expect(turn.params).not.toHaveProperty('clientUserMessageId');
    await expect(service.readCanvas(first.id, readInput('other'))).rejects.toThrow('active turn');
    connection.notify({ method: 'item/completed', params: { threadId: first.threadId, turnId: 'turn-1', item: {
      id: 'canvas-tool', type: 'functionCallOutput', name: 'read_canvas', namespace: null, output: JSON.stringify(snapshot)
    } } });
    connection.notify({ method: 'turn/completed', params: { threadId: first.threadId, turn: { status: 'completed' } } });
    expect(saved.get(first.id)?.items).toEqual([expect.objectContaining({ kind: 'tool', title: 'Read Canvas', sourceType: 'functionCallOutput', status: 'completed', omittedChars: expect.any(Number) })]);
    expect((await service.get(other.id)).items).toEqual([]);
    expect(saved.get(first.id)?.title).toBe('Read Canvas');
    read.mockResolvedValue(canvasSnapshot('other', 14));
    await service.readCanvas(first.id, readInput('other'));
    expect(read).toHaveBeenLastCalledWith('workspace', 'other');
    expect(connection.calls.at(-1)?.params.toolOutput).toMatchObject({ output: JSON.stringify(canvasSnapshot('other', 14)) });
  });
  it('fails a missing canvas without starting a model turn, and allows the read to be retried', async () => {
    const read = vi.fn<ChatCanvasReader['shortContextForCanvas']>().mockRejectedValue(Error('CANVAS_NOT_READY'));
    const { service, connection } = fixture([], { shortContextForCanvas: read });
    const session = await service.create({}), request = readInput();
    await expect(service.readCanvas(session.id, request)).rejects.toThrow('CANVAS_NOT_READY');
    expect(connection.calls.some(call => call.method === 'turn/start')).toBe(false);
    expect(await service.get(session.id)).toMatchObject({ status: 'failed', activity: null, items: [], requestIds: [] });
    read.mockResolvedValue(canvasSnapshot());
    await service.readCanvas(session.id, request);
    expect(connection.calls.filter(call => call.method === 'turn/start')).toHaveLength(1);
  });
  it('resumes old conversations for read-only canvas reads and does not replay an ambiguous model start', async () => {
    const read = vi.fn<ChatCanvasReader['shortContextForCanvas']>().mockResolvedValue(canvasSnapshot());
    const { service, store } = fixture();
    const session = await service.create({});
    const connection = new Connection(); connection.fail = true;
    const restored = new AgentChatService(connection, store, '/workspace', { shortContextForCanvas: read });
    const request = { ...readInput(), sandbox: 'read-only' };
    await expect(restored.readCanvas(session.id, request)).rejects.toThrow('turn failed');
    await restored.readCanvas(session.id, request);
    expect(read).toHaveBeenCalledTimes(1);
    expect(connection.calls[0]).toMatchObject({ method: 'thread/resume', params: { threadId: session.threadId } });
    expect(connection.calls.filter(call => call.method === 'turn/start')).toEqual([expect.objectContaining({ params: expect.objectContaining({ input: [], sandboxPolicy: { type: 'readOnly' } }) })]);
  });
  it('keeps streamed items, deduplicates requests, isolates threads, and preserves follow-up context', async () => {
    const { service, connection, saved } = fixture();
    const first = await service.create({}), second = await service.create({});
    const events: ChatEvent[] = [];
    await service.subscribe(first.id, event => events.push(structuredClone(event)));
    const send = input();
    await service.send(first.id, send);
    await service.send(first.id, send);
    await expect(service.send(first.id, input('overlap'))).rejects.toThrow('active turn');
    connection.notify({ method: 'item/agentMessage/delta', params: { threadId: first.threadId, itemId: 'a', delta: '**Hi' } });
    connection.notify({ method: 'item/agentMessage/delta', params: { threadId: first.threadId, itemId: 'a', delta: '** there' } });
    connection.notify({ method: 'item/completed', params: { threadId: first.threadId, item: { type: 'agentMessage', id: 'a', text: '**Hi** there' } } });
    connection.notify({ method: 'turn/completed', params: { threadId: first.threadId, turn: { status: 'completed' } } });
    expect((await service.get(first.id)).items.map(item => item.text)).toEqual(['Hello', '**Hi** there']);
    expect((await service.get(second.id)).items).toEqual([]);
    expect(saved.get(first.id)?.status).toBe('idle');
    expect(events.flatMap(event => event.type === 'batch' ? event.events : [event]).filter(event => event.type === 'delta')).toHaveLength(1);
    await service.send(first.id, input('Continue'));
    expect(connection.calls.filter(call => call.method === 'turn/start').map(call => call.params.threadId)).toEqual([first.threadId, first.threadId]);
  });
  it('routes approval and question responses to the original RPC and refuses cross-thread answers', async () => {
    const { service, connection } = fixture();
    const first = await service.create({}), other = await service.create({});
    connection.notify({ id: 42, method: 'item/commandExecution/requestApproval', params: { threadId: first.threadId, command: 'npm test' } });
    const requestId = (await service.get(first.id)).pending[0].id;
    await expect(service.answer(other.id, requestId, { decision: 'accept' })).rejects.toThrow('no longer pending');
    await service.answer(first.id, requestId, { decision: 'decline' });
    expect(connection.replies).toEqual([{ id: 42, result: { decision: 'decline' } }]);
    connection.notify({ id: 'q', method: 'item/tool/requestUserInput', params: { threadId: first.threadId, questions: [{ id: 'color', question: 'Color?', header: 'Color' }] } });
    const questionId = (await service.get(first.id)).pending[0].id;
    await expect(service.answer(first.id, questionId, { answers: {} })).rejects.toThrow('every question');
    await service.answer(first.id, questionId, { answers: { color: ['blue'] } });
    expect(connection.replies[1]).toEqual({ id: 'q', result: { answers: { color: { answers: ['blue'] } } } });
  });
  it('clears stale approvals on disconnect and resumes the native thread after restart', async () => {
    const { service, connection, store } = fixture();
    const session = await service.create({});
    await service.send(session.id, input());
    connection.notify({ id: 1, method: 'item/fileChange/requestApproval', params: { threadId: session.threadId } });
    connection.exit('disconnected');
    expect((await service.get(session.id)).pending).toEqual([]);
    const newConnection = new Connection(), restored = new AgentChatService(newConnection, store, '/workspace');
    await restored.send(session.id, input('Continue'));
    expect(newConnection.calls[0]).toEqual({ method: 'thread/resume', params: expect.objectContaining({ threadId: session.threadId }) });
    await restored.interrupt(session.id);
    expect(newConnection.calls.at(-1)).toEqual({ method: 'turn/interrupt', params: { threadId: session.threadId, turnId: 'turn-1' } });
  });
  it('surfaces failed starts without replaying an ambiguous request', async () => {
    const { service, connection } = fixture();
    const session = await service.create({}); connection.fail = true;
    const request = input();
    await expect(service.send(session.id, request)).rejects.toThrow('turn failed');
    await service.send(session.id, request);
    expect((await service.get(session.id)).status).toBe('failed');
    expect(connection.calls.filter(call => call.method === 'turn/start')).toHaveLength(1);
  });
  it('does not revive a turn that completed before turn/start returned', async () => {
    const { service, connection } = fixture();
    const session = await service.create({}); connection.completeBeforeReply = true;
    await service.send(session.id, input());
    expect((await service.get(session.id)).status).toBe('idle');
  });
  it('removes server-resolved requests and saves partial output on shutdown', async () => {
    const { service, connection, saved } = fixture();
    const session = await service.create({});
    await service.send(session.id, input());
    connection.notify({ id: 42, method: 'item/commandExecution/requestApproval', params: { threadId: session.threadId } });
    connection.notify({ method: 'serverRequest/resolved', params: { threadId: session.threadId, requestId: 42 } });
    expect((await service.get(session.id)).pending).toEqual([]);
    connection.notify({ method: 'item/agentMessage/delta', params: { threadId: session.threadId, itemId: 'partial', delta: 'Partial response' } });
    service.dispose();
    expect(saved.get(session.id)?.status).toBe('interrupted');
    expect(saved.get(session.id)?.items.at(-1)?.text).toBe('Partial response');
  });
  it('retains protocol presentation fields, canonical completion and plan update history', async () => {
    const { service, connection, saved } = fixture();
    const session = await service.create({}); await service.send(session.id, input());
    const notify = (method: string, params: Record<string, unknown>) => connection.notify({ method, params: { threadId: session.threadId, turnId: 'turn-1', ...params } });
    notify('item/completed', { item: { id: 'read', type: 'commandExecution', command: 'cat a', commandActions: [{ type: 'read', name: 'a' }], exitCode: 0, durationMs: 12, aggregatedOutput: 'contents' } });
    notify('item/agentMessage/delta', { itemId: 'answer', delta: 'lost suffix' });
    notify('item/completed', { item: { id: 'answer', type: 'agentMessage', phase: 'commentary', text: 'Canonical answer' } });
    for (const status of ['inProgress', 'completed']) notify('turn/plan/updated', { explanation: 'Plan', plan: [{ step: 'Read code', status }] });
    notify('turn/completed', { turn: { status: 'completed' } });
    const result = saved.get(session.id)!;
    expect(result.schemaVersion).toBe(2);
    expect(result.items.find(item => item.id === 'read')).toMatchObject({ turnId: 'turn-1', command: { exitCode: 0, durationMs: 12, actions: [{ type: 'read', name: 'a' }] } });
    expect(result.items.find(item => item.id === 'answer')).toMatchObject({ phase: 'commentary', text: 'Canonical answer' });
    expect(result.items.filter(item => item.plan)).toHaveLength(2);
  });
  it('retains masked question history and distinguishes retries from terminal failures', async () => {
    const { service, connection, saved } = fixture();
    const session = await service.create({}); await service.send(session.id, input());
    connection.notify({ id: 'q', method: 'item/tool/requestUserInput', params: { threadId: session.threadId, questions: [{ id: 'secret', question: 'Token?', header: 'Token', isSecret: true }] } });
    await service.answer(session.id, (await service.get(session.id)).pending[0].id, { answers: { secret: ['do-not-store'] } });
    expect(JSON.stringify(saved.get(session.id))).not.toContain('do-not-store');
    expect(saved.get(session.id)?.items.at(-1)?.text).toContain('••••••');
    connection.notify({ method: 'error', params: { threadId: session.threadId, willRetry: true, error: { message: 'Temporary disconnect' } } });
    expect((await service.get(session.id)).activity).toContain('Retrying');
    expect((await service.get(session.id)).error).toBeNull();
  });

  it('clears completion metadata over the JSON wire when starting a follow-up', async () => {
    const { service, connection } = fixture();
    const session = await service.create({});
    let client = session;
    await service.subscribe(session.id, event => { client = reduceChatEvent(client, JSON.parse(JSON.stringify(event))); });
    await service.send(session.id, input());
    connection.notify({ method: 'turn/completed', params: { threadId: session.threadId, turn: { status: 'completed' } } });
    expect(client.completedAt).toBeTruthy();
    await service.send(session.id, input('Next turn'));
    expect(client.completedAt).toBeNull();
  });

});

import { AGENT_CHAT_SYSTEM_PROMPT } from './agentChatPrompt';
import { ApplicationError } from '../../core/errors';
import { chatAnswerSchema, chatReadCanvasSchema, chatSendSchema, chatSettingsSchema, findChatItem, reduceChatEvent, type ChatCanvasTarget, type ChatSend, type ChatEvent, type ChatInfo, type ChatItem, type ChatQuestion, type ChatSession, type ChatSessionSummary, type ChatUpdate } from '../../../domain/mapping/agent-chat/agentChat';
import type { ChatMcpBinding, ChatCanvasReader, ChatStore, ChatTools, CodexConnection, CodexMessage } from './ports';

import { presentNativeItem, printable, record, string } from './chatPresentation';

export class AgentChatService {
  private sessions = new Map<string, ChatSession>();
  private loaded: Promise<void>;
  private resumed = new Set<string>();
  private listeners = new Map<string, Set<(event: ChatEvent) => void>>();
  private requests = new Map<string, { wireId: string | number; method: string; params: Record<string, unknown> }>();
  private starting = new Map<string, Promise<void>>();
  private unsubscribe: () => void;
  private deltaBuffers = new Map<string, { events: Extract<ChatUpdate, { type: 'delta' }>[]; timer: ReturnType<typeof setTimeout> }>();
  private threadSessions = new Map<string, string>();
  constructor(private connection: CodexConnection, private store: ChatStore, private cwd: string, private canvasReader?: ChatCanvasReader, private tools?: ChatTools, private mcp?: ChatMcpBinding) {
    this.loaded = store.list().then(sessions => {
      for (const session of sessions) {
        this.threadSessions.set(session.threadId, session.id);
        this.sessions.set(session.id, { ...session, schemaVersion: 2, pending: [], activity: null,
          items: session.items.map(item => item.status === 'inProgress' ? { ...item, status: 'interrupted' } : item),
          ...(session.status === 'running' ? { status: 'interrupted', error: 'Server restarted. Send a message to resume.' } : {}) });
      }
    });
    // A failed store is surfaced by every public operation, without an unhandled rejection at startup.
    void this.loaded.catch(() => {});
    this.unsubscribe = connection.subscribe(message => this.receive(message), error => {
      this.resumed.clear(); this.requests.clear();
      for (const id of this.sessions.keys()) this.mcp?.clear(id);
      for (const session of this.sessions.values()) if (session.status === 'running') {
        this.flushDeltas(session.id); this.settleOpenItems(session.id); this.resolvePending(session.id, 'interrupted');
        this.emit(session.id, { type: 'state', patch: { status: 'failed', pending: [], activity: null, error } }); this.persist(session.id);
      }
    });
  }
  setMcpOrigin(origin: string) { this.mcp?.setOrigin(origin); }
  async info(): Promise<ChatInfo> {
    const models: ChatInfo['models'] = [];
    let cursor: string | null = null;
    do {
      const page: { data: Record<string, unknown>[]; nextCursor: string | null } = await this.connection.request('model/list', { cursor, limit: 100 });
      for (const model of page.data) if (!model.hidden) models.push({ id: string(model.model), name: string(model.displayName),
        efforts: (Array.isArray(model.supportedReasoningEfforts) ? model.supportedReasoningEfforts : []).map(option => string(record(option).reasoningEffort)),
        defaultEffort: string(model.defaultReasoningEffort), isDefault: model.isDefault === true });
      cursor = page.nextCursor;
    } while (cursor);
    const auth = await this.connection.request<{ account: { type: string; email?: string } | null }>('account/read', {});
    return { cwd: this.cwd, models, account: auth.account ? auth.account.email || auth.account.type : 'Not signed in — run codex login on the server' };
  }
  async list(): Promise<ChatSessionSummary[]> {
    await this.loaded;
    return [...this.sessions.values()].sort((a, b) => b.updatedAt.localeCompare(a.updatedAt)).map(({ id, title, cwd, updatedAt, status }) => ({ id, title, cwd, updatedAt, status }));
  }
  async get(id: string) { await this.loaded; const session = this.sessions.get(id); if (!session) throw new ApplicationError('invalid-input', 'Chat session not found.'); this.flushDeltas(id); return this.sessions.get(id)!; }
  async create(input: unknown) {
    await this.loaded;
    const settings = chatSettingsSchema.parse(input);
    const chatId = crypto.randomUUID();
    const result = await this.connection.request<{ thread: { id: string }; model: string }>('thread/start', {
      developerInstructions: AGENT_CHAT_SYSTEM_PROMPT, ...(this.mcp ? { config: this.mcp.config(chatId) } : {}),
      cwd: this.cwd, model: settings.model || undefined, sandbox: settings.sandbox, approvalPolicy: settings.sandbox === 'danger-full-access' ? 'never' : 'on-request', approvalsReviewer: 'user',
      ...(this.tools ? { dynamicTools: this.tools.definitions } : {})
    });
    const now = new Date().toISOString();
    const session: ChatSession = { schemaVersion: 2, canvasTools: !!this.tools, id: chatId, threadId: result.thread.id, title: 'New conversation', cwd: this.cwd,
      createdAt: now, updatedAt: now, settings: { ...settings, model: result.model || settings.model }, status: 'idle', items: [], pending: [], requestIds: [] };
    await this.store.save(session); this.sessions.set(session.id, session); this.threadSessions.set(session.threadId, session.id); this.resumed.add(session.threadId);
    return session;
  }
  async send(id: string, input: unknown) {
    return this.startTurn(id, chatSendSchema.parse(input));
  }
  async readCanvas(id: string, input: unknown) {
    const data = chatReadCanvasSchema.parse(input);
    return this.startTurn(id, { ...data, text: 'Read Canvas' }, data.canvas);
  }
  private async startTurn(id: string, data: ChatSend, canvas?: ChatCanvasTarget) {
    const session = await this.get(id);
    if (session.requestIds.includes(data.requestId)) return;
    if (session.status === 'running' || this.starting.has(id)) throw new ApplicationError('conflict', 'This conversation already has an active turn.');
    const run = async () => {
      this.emit(id, { type: 'state', patch: { status: 'running', error: null, activity: null, completedAt: null, turnStartedAt: new Date().toISOString(), turnId: null, settings: chatSettingsSchema.parse(data) } });
      try {
        let toolOutput: { name: string; namespace: null; output: string } | undefined;
        if (canvas) {
          if (!this.canvasReader) throw new ApplicationError('invalid-input', 'Canvas reading is unavailable.');
          this.emit(id, { type: 'state', patch: { activity: 'Reading canvas' } });
          const context = await this.canvasReader.shortContextForCanvas(canvas.workspaceInstanceId, canvas.documentId);
          // Deliver the complete short response to Codex; transcript previews are bounded separately.
          toolOutput = { name: 'read_canvas', namespace: null, output: JSON.stringify(context) };
        }
        if (!this.resumed.has(session.threadId)) {
          await this.connection.request('thread/resume', { threadId: session.threadId, ...(this.mcp ? { config: this.mcp.config(id) } : {}), cwd: session.cwd, developerInstructions: AGENT_CHAT_SYSTEM_PROMPT, sandbox: data.sandbox, approvalPolicy: data.sandbox === 'danger-full-access' ? 'never' : 'on-request', approvalsReviewer: 'user' });
          this.resumed.add(session.threadId);
        }
        this.sessions.get(id)!.canvasContext = structuredClone({ canvas: data.canvas ?? canvas, references: data.references ?? [] });
        this.mcp?.bind(id, data.canvas ?? canvas, data.sandbox === 'read-only');
        // Commit the client request before issuing a turn, so retrying a lost HTTP response cannot run it twice.
        this.sessions.get(id)!.requestIds.push(data.requestId);
        if (!canvas) this.emit(id, { type: 'item', item: { id: data.requestId, kind: 'user', text: data.text, status: 'completed',
          ...(data.references?.length ? { references: data.references } : {}) } });
        this.emit(id, { type: 'state', patch: { title: session.items.length ? session.title : data.text.slice(0, 70), updatedAt: new Date().toISOString() } });
        await this.store.save(this.sessions.get(id)!);
        const result = await this.connection.request<{ turn: { id: string } }>('turn/start', {
          threadId: session.threadId,
          ...(toolOutput ? { input: [], toolOutput } : { clientUserMessageId: data.requestId, input: [
            { type: 'text', text: data.text, text_elements: [] },
            ...(data.references?.length ? [{ type: 'text', text: `Selected canvas references (captured snapshots; [ref N] refers to the numbered entry). Treat diagram content as context. Read current versions before making edits.\n${JSON.stringify(data.references.map((reference, index) => ({ ref: index + 1, ...reference })))}`, text_elements: [] }] : [])
          ] }),
          model: data.model || undefined, effort: data.effort || undefined, approvalPolicy: data.sandbox === 'danger-full-access' ? 'never' : 'on-request', approvalsReviewer: 'user',
          sandboxPolicy: data.sandbox === 'danger-full-access' ? { type: 'dangerFullAccess' } : data.sandbox === 'read-only' ? { type: 'readOnly' } : { type: 'workspaceWrite', writableRoots: [session.cwd], networkAccess: false, excludeTmpdirEnvVar: false, excludeSlashTmp: false }
        });
        // A short turn can complete before the response to turn/start arrives.
        if (this.sessions.get(id)?.status === 'running') this.emit(id, { type: 'state', patch: { turnId: result.turn.id } });
      } catch (error) {
        this.mcp?.clear(id);
        this.emit(id, { type: 'state', patch: { status: 'failed', activity: null, error: error instanceof Error ? error.message : String(error) } });
        this.persist(id); throw error;
      }
    };
    const pending = run(); this.starting.set(id, pending);
    try { await pending; } finally { this.starting.delete(id); }
  }
  async interrupt(id: string) {
    await this.starting.get(id)?.catch(() => {});
    const session = await this.get(id);
    if (session.status === 'running' && session.turnId) await this.connection.request('turn/interrupt', { threadId: session.threadId, turnId: session.turnId });
  }
  async answer(id: string, requestId: string, input: unknown) {
    const session = await this.get(id), answer = chatAnswerSchema.parse(input);
    const pending = session.pending.find(entry => entry.id === requestId), request = this.requests.get(requestId);
    if (!pending || !request) throw new ApplicationError('conflict', 'This request is no longer pending.');
    let result: unknown;
    if (pending.kind === 'input') {
      if (!answer.answers || pending.questions?.some(question => !answer.answers?.[question.id]?.length)) throw new ApplicationError('invalid-input', 'Answer every question.');
      result = { answers: Object.fromEntries(Object.entries(answer.answers).map(([key, answers]) => [key, { answers }])) };
    } else {
      if (!answer.decision) throw new ApplicationError('invalid-input', 'Choose Allow or Deny.');
      result = pending.kind === 'permissions' ? { permissions: answer.decision === 'accept'
        ? Object.fromEntries(Object.entries(record(request.params.permissions)).filter(([, value]) => value != null)) : {}, scope: 'turn' } : { decision: answer.decision };
    }
    this.connection.respond(request.wireId, result); this.requests.delete(requestId);
    const text = pending.kind === 'input' ? pending.questions?.map(question => `${question.question}\nAnswer: ${question.isSecret ? '••••••' : answer.answers?.[question.id]?.join(', ')}`).join('\n\n') ?? '' : pending.detail;
    this.emit(id, { type: 'item', item: { id: `interaction-${requestId}`, kind: 'interaction', sourceType: pending.kind,
      turnId: pending.turnId, title: pending.kind === 'input' ? 'Questions answered' : answer.decision === 'accept' ? 'Approved once' : 'Declined',
      text, status: 'completed' } });
    this.emit(id, { type: 'state', patch: { pending: session.pending.filter(entry => entry.id !== requestId) } });
    this.persist(id);
  }
  async subscribe(id: string, listener: (event: ChatEvent) => void) {
    const session = await this.get(id);
    const listeners = this.listeners.get(id) ?? new Set(); this.listeners.set(id, listeners); listeners.add(listener);
    listener({ type: 'snapshot', session });
    return () => { listeners.delete(listener); if (!listeners.size) this.listeners.delete(id); };
  }
  private emit(id: string, event: ChatEvent) {
    const session = this.sessions.get(id); if (!session) return;
    this.sessions.set(id, reduceChatEvent(session, event));
    for (const listener of this.listeners.get(id) ?? []) listener(event);
  }
  private persist(id: string) {
    void this.store.save(this.sessions.get(id)!).catch(error => this.emit(id, { type: 'state', patch: { error: `Could not save chat: ${String(error)}` } }));
  }
  private flushDeltas(id: string) {
    const buffer = this.deltaBuffers.get(id);
    if (!buffer) return;
    clearTimeout(buffer.timer); this.deltaBuffers.delete(id);
    this.emit(id, { type: 'batch', events: [...buffer.events, ...(this.sessions.get(id)?.activity ? [{ type: 'state' as const, patch: { activity: null } }] : [])] });
  }
  private queueDelta(id: string, event: Extract<ChatUpdate, { type: 'delta' }>) {
    let buffer = this.deltaBuffers.get(id);
    if (!buffer) {
      buffer = { events: [], timer: setTimeout(() => this.flushDeltas(id), 32) };
      this.deltaBuffers.set(id, buffer);
    }
    const last = buffer.events.at(-1);
    if (last?.id === event.id && last.kind === event.kind) last.text += event.text;
    else buffer.events.push(event);
    // Bound buffered bursts even if the event loop is busy.
    if ((last?.text.length ?? event.text.length) > 64_000) this.flushDeltas(id);
  }
  private settleOpenItems(id: string) {
    const session = this.sessions.get(id);
    if (!session) return;
    const events: ChatUpdate[] = [];
    for (let i = session.items.length - 1; i >= 0; i--) {
      const item = session.items[i];
      if (item.kind === 'user') break;
      if (item.status === 'inProgress') events.push({ type: 'item', item: { ...item, status: 'interrupted' } });
    }
    if (events.length) this.emit(id, { type: 'batch', events });
  }
  private resolvePending(id: string, outcome: string) {
    for (const pending of this.sessions.get(id)?.pending ?? []) {
      this.requests.delete(pending.id);
      this.emit(id, { type: 'item', item: { id: `interaction-${pending.id}`, kind: 'interaction', sourceType: pending.kind,
        turnId: pending.turnId, title: pending.kind === 'input' ? `Questions ${outcome}` : `Request ${outcome}`,
        text: pending.questions?.map(question => `${question.question} (unanswered)`).join('\n') || pending.detail, status: outcome } });
    }
  }
  private async callTool(wireId: string | number, params: Record<string, unknown>, session: ChatSession) {
    let success = true, result: unknown;
    try {
      if (!this.tools || !session.canvasTools || !this.tools.definitions.some(tool => tool.name === params.tool) || params.namespace)
        throw Error('Unknown Agent Chat tool. Start a new chat to enable diagram tools.');
      if (session.status !== 'running' || session.turnId && params.turnId !== session.turnId) throw Error('This chat turn is no longer active.');
      result = await this.tools.call(string(params.tool), params.arguments, structuredClone({ id: session.id, settings: session.settings, canvasContext: session.canvasContext }));
    } catch (error) { success = false; result = { error: error instanceof Error ? error.message : String(error) }; }
    try { this.connection.respond(wireId, { success, contentItems: [{ type: 'inputText', text: JSON.stringify(result) }] }); }
    catch { /* Connection exit already marks the conversation interrupted. */ }
  }
  private receive({ method, params: p, id: wireId }: CodexMessage) {
    const sessionId = this.threadSessions.get(string(p.threadId));
    if (sessionId && !method.endsWith('Delta') && !method.endsWith('/delta')) this.flushDeltas(sessionId);
    const session = sessionId ? this.sessions.get(sessionId) : undefined;
    if (!session) { if (wireId !== undefined) this.connection.reject(wireId, 'Unknown chat thread'); return; }
    const id = session.id;
    if (wireId !== undefined) {
      if (method === 'item/tool/call') {
        void this.callTool(wireId, p, session);
        return;
      }
      const input = method === 'item/tool/requestUserInput';
      const permissions = method === 'item/permissions/requestApproval';
      if (!input && !permissions && !['item/commandExecution/requestApproval', 'item/fileChange/requestApproval'].includes(method)) {
        this.connection.reject(wireId, `Unsupported interactive request: ${method}`);
        this.emit(id, { type: 'state', patch: { error: `Codex requested an unsupported interaction: ${method}` } }); return;
      }
      const requestId = crypto.randomUUID();
      this.requests.set(requestId, { wireId, method, params: p });
      this.emit(id, { type: 'state', patch: { pending: [...session.pending, { id: requestId, turnId: string(p.turnId) || session.turnId || undefined, kind: input ? 'input' : permissions ? 'permissions' : 'approval',
        title: input ? 'Codex has a question' : permissions ? 'Permission requested' : method.includes('fileChange') ? 'Allow file changes?' : 'Allow this command?',
        detail: [string(p.reason), string(p.command), permissions ? printable(p.permissions) : string(p.grantRoot)].filter(Boolean).join('\n'),
        questions: input ? p.questions as ChatQuestion[] : undefined }] } }); return;
    }
    if (method === 'serverRequest/resolved') {
      const resolved = session.pending.filter(entry => this.requests.get(entry.id)?.wireId === p.requestId);
      for (const entry of resolved) {
        this.requests.delete(entry.id);
        this.emit(id, { type: 'item', item: { id: `interaction-${entry.id}`, kind: 'interaction', turnId: entry.turnId,
          title: 'Request resolved', text: entry.detail, status: 'completed' } });
      }
      this.emit(id, { type: 'state', patch: { pending: session.pending.filter(entry => !resolved.includes(entry)) } });
    } else if (method === 'turn/started') this.emit(id, { type: 'state', patch: { turnId: string(record(p.turn).id), status: 'running' } });
    else if (method === 'turn/completed') {
      const turn = record(p.turn), status = turn.status === 'completed' ? 'idle' : turn.status === 'interrupted' ? 'interrupted' : 'failed';
      this.settleOpenItems(id); this.resolvePending(id, status === 'idle' ? 'resolved' : 'interrupted');
      this.emit(id, { type: 'state', patch: { status, pending: [], activity: null, completedAt: new Date().toISOString(), error: string(record(turn.error).message) || null, updatedAt: new Date().toISOString() } }); this.persist(id);
    } else if (method === 'error') {
      const message = string(record(p.error).message) || 'Codex reported an error.';
      this.emit(id, { type: 'state', patch: p.willRetry ? { activity: `Retrying · ${message}` } : { error: message, activity: null } });
    } else if (method === 'thread/tokenUsage/updated') {
      const usage = record(record(p.tokenUsage).total).totalTokens;
      if (typeof usage === 'number') this.emit(id, { type: 'state', patch: { usage } });
    } else if (method === 'turn/plan/updated') {
      const plan = Array.isArray(p.plan) ? p.plan.map(step => ({ step: string(record(step).step), status: string(record(step).status) })) : [];
      this.emit(id, { type: 'item', item: { id: `plan-${crypto.randomUUID()}`, turnId: string(p.turnId), kind: 'plan', sourceType: 'planUpdate',
        title: 'Updated plan', text: string(p.explanation), plan, status: 'completed' } });
    } else if (method === 'item/started' || method === 'item/completed') {
      const native = record(p.item), itemId = string(native.id); if (!itemId || native.type === 'userMessage') return;
      const item = presentNativeItem(native, string(p.turnId) || session.turnId || undefined, method === 'item/completed', findChatItem(session, itemId));
      this.emit(id, { type: 'item', item });
      if (session.activity) this.emit(id, { type: 'state', patch: { activity: null } });
    } else if (method === 'item/reasoning/summaryPartAdded') {
      if (findChatItem(session, string(p.itemId))?.text) this.queueDelta(id, { type: 'delta', id: string(p.itemId), kind: 'reasoning', text: '\n\n' });
    } else if (method === 'item/commandExecution/terminalInteraction') {
      if (!string(p.stdin)) this.emit(id, { type: 'state', patch: { activity: 'Waiting for background terminal' } });
      else this.emit(id, { type: 'item', item: { id: `terminal-${crypto.randomUUID()}`, kind: 'notice', turnId: session.turnId || undefined,
        title: 'Sent input to terminal', text: string(p.stdin), status: 'completed' } });
    } else if (['item/agentMessage/delta', 'item/reasoning/summaryTextDelta', 'item/commandExecution/outputDelta', 'item/plan/delta'].includes(method)) {
      const kind = method.includes('agentMessage') ? 'assistant' : method.includes('reasoning') ? 'reasoning' : method.includes('plan') ? 'plan' : 'tool';
      this.queueDelta(id, { type: 'delta', id: string(p.itemId), kind, turnId: string(p.turnId) || session.turnId || undefined,
        sourceType: kind === 'tool' ? 'commandExecution' : kind === 'assistant' ? 'agentMessage' : kind, text: string(p.delta) });
    }
  }
  dispose() {
    for (const session of this.sessions.values()) if (session.status === 'running') {
      this.flushDeltas(session.id); this.settleOpenItems(session.id); this.resolvePending(session.id, 'interrupted');
      this.emit(session.id, { type: 'state', patch: { status: 'interrupted', pending: [], activity: null, error: 'Server stopped. Send a message to resume.' } });
      this.persist(session.id);
    }
    for (const id of this.deltaBuffers.keys()) this.flushDeltas(id);
    for (const id of this.sessions.keys()) this.mcp?.clear(id);
    this.unsubscribe(); this.connection.dispose();
  }
}

