import { expect, it } from 'vitest';
import type { ChatReference } from '../../../../domain/mapping/agent-chat/agentChat';
import { promptText } from '../prompt-composer/promptBody';
import { draftLength, replaceChatDraft, serializeChatDraft, sliceChatDraft, type ChatDraft } from './chatDraft';

const reference = (label: string): ChatReference => ({ canvas: { workspaceInstanceId: 'workspace', documentId: 'doc' }, canvasName: 'Canvas', displayNodeId: 'grid:overview',
  reference: { kind: 'diagram', label, diagramId: label, revisionId: 'pinned-revision' }, ascii: `${label}\n  Child` });
const chip = (label: string): ChatDraft[number] => ({ kind: 'reference', id: label, reference: reference(label) });

it('keeps marker positions and independently captured reference data in the same order', () => {
  const draft = [promptText('Explain '), chip('Service'), promptText(' to '), chip('Bridge'), promptText('\nwithout changing selection.')];
  const result = serializeChatDraft(draft);
  expect(result.prompt).toBe('Explain [ref 1] to [ref 2]\nwithout changing selection.');
  expect(result.references.map(ref => ref.reference.label)).toEqual(['Service', 'Bridge']);
  result.references[0].ascii = 'Changed externally';
  expect(serializeChatDraft(draft).references[0].ascii).toBe('Service\n  Child');
});

it('inserts at a text cursor and removes an entire chip at a one-character boundary', () => {
  const draft = replaceChatDraft([promptText('Explain  now')], 8, 8, [chip('Service')]);
  expect(serializeChatDraft(draft).prompt).toBe('Explain [ref 1] now');
  expect(draftLength(draft)).toBe('Explain  now'.length + 1);
  const removed = replaceChatDraft(draft, 8, 9, []);
  expect(serializeChatDraft(removed)).toEqual({ prompt: 'Explain  now', references: [] });
});

it('handles selections crossing text and references, renumbering surviving attachments', () => {
  const draft = [promptText('a'), chip('First'), promptText('bc'), chip('Second'), promptText('d')];
  expect(serializeChatDraft(sliceChatDraft(draft, 1, 5)).prompt).toBe('[ref 1]bc[ref 2]');
  const replaced = replaceChatDraft(draft, 0, 4, [promptText('Only ')]);
  expect(serializeChatDraft(replaced)).toEqual({ prompt: 'Only [ref 1]d', references: [reference('Second')] });
  const duplicate = replaceChatDraft(draft, 6, 6, sliceChatDraft(draft, 1, 2));
  expect(new Set(duplicate.map(block => block.id)).size).toBe(duplicate.length);
  expect(serializeChatDraft(duplicate).references.map(ref => ref.reference.label)).toEqual(['First', 'Second', 'First']);
});

it('does not infer attachments from manually typed marker text', () => {
  expect(serializeChatDraft([promptText('Literal [ref 1]')])).toEqual({ prompt: 'Literal [ref 1]', references: [] });
});

import type { ChatReference } from '../../../../domain/mapping/agent-chat/agentChat';
import { normalizePromptBody, promptText, serializePromptBody, type PromptBodyBlock } from '../prompt-composer/promptBody';

export type ChatDraft = readonly PromptBodyBlock<ChatReference>[];
export const emptyChatDraft = (): ChatDraft => [promptText()];
export const serializeChatDraft = (draft: ChatDraft) => serializePromptBody(draft);
export const draftLength = (draft: ChatDraft) => draft.reduce((size, block) => size + (block.kind === 'text' ? block.text.length : 1), 0);

/** Offsets count a complete reference as one character, including when a text selection crosses it. */
export function sliceChatDraft(draft: ChatDraft, start: number, end = draftLength(draft)): ChatDraft {
  let offset = 0;
  return draft.flatMap(block => {
    const length = block.kind === 'text' ? block.text.length : 1;
    const from = Math.max(0, start - offset), to = Math.min(length, end - offset);
    offset += length;
    if (from >= to) return [];
    return [block.kind === 'text' ? { ...block, text: block.text.slice(from, to) } : block];
  });
}
export function replaceChatDraft(draft: ChatDraft, start: number, end: number, inserted: ChatDraft): ChatDraft {
  // New identities also make pasted copies independent of their originals.
  return normalizePromptBody([...sliceChatDraft(draft, 0, start), ...inserted, ...sliceChatDraft(draft, end)]
    .map(block => ({ ...block, id: crypto.randomUUID() })));
}

import { normalizePromptBody, promptText } from '../prompt-composer/promptBody';
import { draftLength, type ChatDraft } from './chatDraft';

export interface DraftSelection { anchor: number; focus: number }
const chipId = (node: Node) => node instanceof HTMLElement ? node.dataset.referenceId : undefined;
const tail = (node: Node) => node instanceof HTMLElement && node.hasAttribute('data-editor-tail');
export function readDraftDom(root: Node, source: ChatDraft): ChatDraft {
  const references = new Map(source.filter(block => block.kind === 'reference').map(block => [block.id, block]));
  const walk = (node: Node): ChatDraft => {
    if (tail(node)) return [];
    const id = chipId(node);
    if (id) return references.has(id) ? [references.get(id)!] : [];
    if (node.nodeType === Node.TEXT_NODE) return [promptText(node.textContent ?? '')];
    if (node.nodeName === 'BR') return [promptText('\n')];
    return Array.from(node.childNodes).flatMap((child, index) => [
      ...(index && ['DIV', 'P'].includes(child.nodeName) ? [promptText('\n')] : []), ...walk(child)
    ]);
  };
  return normalizePromptBody(walk(root));
}

export function readDraftSelection(root: HTMLElement, source: ChatDraft): DraftSelection | undefined {
  const selection = window.getSelection();
  if (!selection?.anchorNode || !selection.focusNode || !root.contains(selection.anchorNode) || !root.contains(selection.focusNode)) return;
  const offset = (node: Node, position: number) => {
    const chip = (node instanceof Element ? node : node.parentElement)?.closest('[data-reference-id]');
    const range = document.createRange(); range.selectNodeContents(root);
    if (chip) range.setEndBefore(chip); else range.setEnd(node, position);
    return draftLength(readDraftDom(range.cloneContents(), source));
  };
  return { anchor: offset(selection.anchorNode, selection.anchorOffset), focus: offset(selection.focusNode, selection.focusOffset) };
}

export function placeDraftSelection(root: HTMLElement, selection: DraftSelection) {
  const point = (offset: number): [Node, number] => {
    for (const child of root.childNodes) {
      const length = tail(child) ? 0 : chipId(child) ? 1 : child.textContent?.length ?? 0;
      if (child.nodeType === Node.TEXT_NODE && offset <= length) return [child, offset];
      if (chipId(child) && offset === 0) return [root, Array.from(root.childNodes).indexOf(child as ChildNode)];
      offset -= length;
    }
    return [root, root.childNodes.length - (root.lastChild && tail(root.lastChild) ? 1 : 0)];
  };
  const [anchor, anchorOffset] = point(Math.max(0, selection.anchor));
  const [focus, focusOffset] = point(Math.max(0, selection.focus));
  root.focus({ preventScroll: true });
  window.getSelection()?.setBaseAndExtent(anchor, anchorOffset, focus, focusOffset);
}

/** Own the editable DOM explicitly: React must not reconcile nodes the browser is typing into. */
export function renderDraftDom(root: HTMLElement, draft: ChatDraft) {
  let number = 0;
  const nodes = draft.map(block => {
    if (block.kind === 'text') return document.createTextNode(block.text);
    const { reference, canvasName } = block.reference;
    const chip = document.createElement('span');
    chip.contentEditable = 'false'; chip.dataset.referenceId = block.id; chip.className = 'agent-chat-reference';
    chip.title = `${canvasName} · ${reference.kind === 'diagram' ? 'Whole diagram' : `Lines ${reference.range.startLine}–${reference.range.endLine}`} · ${reference.revisionId}`;
    const label = document.createElement('span'); label.textContent = reference.label;
    const marker = document.createElement('small'); marker.textContent = `[ref ${++number}]`;
    const remove = document.createElement('button'); remove.type = 'button'; remove.tabIndex = -1; remove.textContent = '×';
    remove.setAttribute('aria-label', `Remove reference ${number}: ${reference.label}`);
    chip.append(marker, label, remove);
    return chip;
  });
  // A trailing line break gives an empty final line a visible caret without adding prompt text.
  const br = document.createElement('br'); br.dataset.editorTail = '';
  root.replaceChildren(...nodes, br);
}

