import { Children, createContext, useContext, isValidElement, memo, useEffect, useId, useMemo, useState, type ReactElement } from 'react';
import { ChatHighlightLink } from '../ChatHighlightLink';
import ReactMarkdown, { defaultUrlTransform, type Components } from 'react-markdown';
import remarkGfm from 'remark-gfm';
import remarkBreaks from 'remark-breaks';
import { createIncrementalMarkdownPlugin } from './markdown-incremental';
import { remarkNormalizeListItemIndentation } from './markdown-list-indentation';
import { remarkGithubAlerts } from './markdown-github-alerts';
import { CodexMarkdownTable } from './CodexMarkdownTable';
import { ChatFileLink } from '../ChatFileLinks';
import { CopyButton } from './CopyButton';
import { CopyToCanvasButton } from '../ChatCanvasCopy';
import { useTheme, themeDefinitions } from '../../../../shared/theme/theme';

export const MarkdownActivityContext = createContext(true);

// Port of T3 Code's CodexMarkdown/ChatMarkdown pipeline (40596072).
// The app-specific media, PR, and desktop handlers are replaced by browser-safe elements.
const CodeBlock = memo(function CodeBlock({ code, language }: { code: string; language: string }) {
  const theme = useTheme();
  const enabled = useContext(MarkdownActivityContext);
  const diagram = ['', 'text', 'txt', 'plaintext', 'plain', 'ascii', 'diagram'].includes(language.toLowerCase());
  const contentId = useId();
  const [collapsed, setCollapsed] = useState(false);
  const lineCount = useMemo(() => code ? code.split('\n').length : 0, [code]);
  const [highlight, setHighlight] = useState<{ code: string; language: string; theme: string; html: string }>();
  useEffect(() => {
    if (!enabled || diagram || collapsed || (highlight?.code === code && highlight.language === language && highlight.theme === theme)) return;
    let cancelled = false;
    // Throttle highlighting while tokens stream; the plain code remains readable immediately.
    const timer = setTimeout(() => {
      if (code.length > 100_000 || !language) return;
      void import('shiki').then(async ({ bundledLanguagesInfo, codeToHtml }) => {
        const lang = bundledLanguagesInfo.find(entry => entry.id === language || entry.aliases?.includes(language));
        if (!lang) return;
        const html = await codeToHtml(code, { lang: lang.id, theme: themeDefinitions[theme].markdown });
        if (!cancelled) setHighlight({ code, language, theme, html });
      }).catch(() => {});
    }, 120);
    return () => { cancelled = true; clearTimeout(timer); };
  }, [code, language, theme, enabled, diagram, collapsed, highlight]);
  const toggle = <button type="button" className="agent-block-toggle" aria-expanded={!collapsed} aria-controls={contentId}
    onClick={() => setCollapsed(value => !value)}>{collapsed ? `▸ ${lineCount} ${lineCount === 1 ? 'line' : 'lines'} collapsed` : '▾ Collapse'}</button>;
  if (diagram) return <div className="agent-code-block agent-diagram-block">
    <div className="agent-diagram-toggle">{toggle}</div>
    <div id={contentId} hidden={collapsed}>{!collapsed && <pre><code>{code}</code></pre>}</div>
    <div className="agent-diagram-actions"><CopyButton text={code} label="Copy code" /><CopyToCanvasButton text={code} enabled={enabled} /></div>
  </div>;
  return <div className="agent-code-block"><header><span>{language || 'text'}</span>{toggle}<CopyButton text={code} label="Copy code" /></header>
    <div id={contentId} hidden={collapsed}>{!collapsed && (highlight?.code === code && highlight.language === language && highlight.theme === theme ? <div dangerouslySetInnerHTML={{ __html: highlight.html }} /> : <pre><code>{code}</code></pre>)}</div>
  </div>;
});
const components: Components = {
  pre({ children }) {
    const child = Children.toArray(children).find(isValidElement) as ReactElement<{ children?: string; className?: string }> | undefined;
    return child ? <CodeBlock code={String(child.props.children ?? '').replace(/\n$/, '')} language={/language-([^\s]+)/.exec(child.props.className ?? '')?.[1] ?? ''} /> : <pre>{children}</pre>;
  },
  table: ({ node: _node, ...props }) => <CodexMarkdownTable {...props} />,
  a({ href, children, title }) {
    if (!href) return <span>{children}</span>;
    if (href.startsWith('highlight:')) return <ChatHighlightLink href={href}>{children}</ChatHighlightLink>;
    if (/^https?:\/\//i.test(href) || href.startsWith('mailto:')) return <a href={href} title={title} target="_blank" rel="noopener noreferrer">{children}</a>;
    // File references are visible and copyable; never navigate the SPA to a filesystem path.
    return <ChatFileLink href={href}>{children}</ChatFileLink>;
  },
  img: ({ src, alt }) => src && /^https?:\/\//i.test(src) ? <img src={src} alt={alt ?? ''} loading="lazy" referrerPolicy="no-referrer" /> : <span>{alt || 'Image'}</span>,
  blockquote({ children, node }) {
    const alert = node?.properties?.dataAlert;
    return <blockquote data-alert={alert}>{typeof alert === 'string' && <strong className="agent-alert-title">{alert}</strong>}{children}</blockquote>;
  }
};
export const CodexMarkdown = memo(function CodexMarkdown({ text, streaming = false }: { text: string; streaming?: boolean }) {
  const enabled = useContext(MarkdownActivityContext);
  const plugins = useMemo(() => [remarkGfm, remarkGithubAlerts, remarkNormalizeListItemIndentation, remarkBreaks,
    ...(streaming ? [createIncrementalMarkdownPlugin()] : [])], [streaming]);
  return <MarkdownActivityContext.Provider value={enabled && !streaming}><div className="agent-markdown"><ReactMarkdown remarkPlugins={plugins} components={components}
    urlTransform={url => /^(file|highlight):/i.test(url) ? url : defaultUrlTransform(url)}>{text}</ReactMarkdown></div></MarkdownActivityContext.Provider>;
});

// Adapted from T3 Code CodexMarkdownPresentation.tsx; see ../T3CODE-LICENSE.
import {
  Children,
  isValidElement,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ComponentProps,
  type ReactElement,
  type ReactNode,
} from "react";
import { codexTableLayout } from "./codexTableLayout";

import { CopyButton } from "./CopyButton";


type Cell = ReactElement<ComponentProps<"td">>;
function elements(children: ReactNode) {
  return Children.toArray(children).filter(
    (child): child is ReactElement<{ children?: ReactNode }> => isValidElement(child),
  );
}
function plainText(node: ReactNode): string {
  if (Array.isArray(node)) return node.map(plainText).join("");
  if (typeof node === "string" || typeof node === "number") return String(node);
  return elements(node)
    .map((element) => (element.type === "br" ? "\n" : plainText(element.props.children)))
    .join("");
}

export function CodexMarkdownTable({ children, ...props }: ComponentProps<"table">) {

  const container = useRef<HTMLDivElement>(null);
  const table = useRef<HTMLTableElement>(null);
  const ruler = useRef<HTMLSpanElement>(null);
  const [columns, setColumns] = useState(100);
  const rows = useMemo(
    () =>
      elements(children).flatMap((section) =>
        elements(section.props.children).map((row) => ({
          key: row.key,
          cells: elements(row.props.children) as Cell[],
        })),
      ),
    [children],
  );
  const header = rows[0]?.cells ?? [];
  const body = rows.slice(1);
  const layout = useMemo(() => codexTableLayout(
    header.map(plainText),
    body.map((row) => row.cells.map(plainText)),
    columns,
  ), [rows, columns]);

  useEffect(() => {
    const target = container.current;
    const measure = ruler.current;
    if (!target || !measure || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(() => {
      const cellWidth = measure.getBoundingClientRect().width / 10;
      if (cellWidth > 0)
        setColumns(Math.max(1, Math.floor(target.getBoundingClientRect().width / cellWidth)));
    });
    observer.observe(target);
    observer.observe(measure);
    return () => observer.disconnect();
  }, []);

  return (
    <div
      ref={container}
      className="chat-markdown-table-container codex-table"
      data-layout={layout.records ? "records" : "grid"}
      data-stacked={layout.stacked}
    >
      <span ref={ruler} className="codex-cell-ruler" aria-hidden="true">
        0000000000
      </span>
      <table
        {...props}
        ref={table}
        role="table"
        style={{
          ...props.style,
          ...(!layout.records
            ? { width: `${layout.widths.reduce((sum, width) => sum + width + 4, -2)}ch` }
            : {}),
        }}
      >
        {!layout.records && (
          <colgroup>
            {layout.widths.map((width, i) => (
              <col
                key={header[i]?.key}
                style={{ width: `${width + (i === layout.widths.length - 1 ? 2 : 4)}ch` }}
              />
            ))}
          </colgroup>
        )}
        <thead role="rowgroup">
          <tr role="row">
            {header.map((cell) => (
              <th {...cell.props} key={cell.key} scope="col" role="columnheader" />
            ))}
          </tr>
        </thead>
        <tbody role="rowgroup">
          {body.map((row) => (
            <tr key={row.key} role="row">
              {header.map((label, i) => (
                <td
                  {...row.cells[i]?.props}
                  key={label.key}
                  role="cell"
                  style={{
                    ...row.cells[i]?.props.style,
                    ...(layout.records
                      ? {
                          textAlign: "left",
                          gridTemplateColumns: layout.stacked
                            ? "1fr"
                            : `${layout.labelWidth}ch minmax(0, 1fr)`,
                        }
                      : {}),
                  }}
                >
                  {layout.records && (
                    <span className="codex-table-label" data-markdown-copy="" aria-hidden="true">
                      {label.props.children}
                    </span>
                  )}
                  <span className="codex-table-value">{row.cells[i]?.props.children}</span>
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
      <div className="codex-table-actions">
        <CopyButton label="Copy table" text={() => {
          const escape = (value: string) => value.replaceAll("|", "\\|").replaceAll("\n", "<br>");
          const row = (cells: Cell[]) => `| ${cells.map(cell => escape(plainText(cell.props.children))).join(" | ")} |`;
          return [row(header), `| ${header.map(() => "---").join(" | ")} |`, ...body.map(entry => row(entry.cells))].join("\n");
        }} />
      </div>
    </div>
  );
}

import { useState } from 'react';
export function CopyButton({ text, label = 'Copy' }: { text: string | (() => string); label?: string }) {
  const [status, setStatus] = useState('');
  return <button type="button" title={status || label} aria-label={status || label} onBlur={() => setStatus('')}
    onClick={async () => { try { await navigator.clipboard.writeText(typeof text === 'function' ? text() : text); setStatus('Copied'); } catch { setStatus('Copy failed'); } }}>{status || label}</button>;
}

// Copyright 2025 OpenAI. SPDX-License-Identifier: Apache-2.0
// Modified: TypeScript adaptation for T3 Code, ported to WindowPanel; see ../CODEX-LICENSE.
// Browser adaptation of codex-rs/tui/src/markdown_render.rs and table_key_value.rs.
// Widths are measured in monospace cells; padding and gaps consume four cells per column.
type ColumnKind = "token" | "narrative" | "compact";
const length = (text: string) => Array.from(text).length;
const words = (text: string) => text.split(/\s+/).filter(Boolean);
const longestToken = (text: string) => Math.max(0, ...words(text).map(length));
const lineWidth = (text: string) => Math.max(0, ...text.split("\n").map(length));

function wrappedHeight(text: string, width: number): number {
  return text.split("\n").reduce((height, line) => {
    let used = 0;
    let lines = 1;
    for (const word of words(line)) {
      const size = length(word);
      if (used && used + 1 + size > width) {
        lines++;
        used = 0;
      } else if (used) used++;
      lines += Math.floor((size - 1) / width);
      used += ((size - 1) % width) + 1;
    }
    return height + lines;
  }, 0);
}

export function codexTableLayout(
  headers: readonly string[],
  rows: readonly (readonly string[])[],
  columns: number,
) {
  const metrics = headers.map((header, i) => {
    const cells = rows.map((row) => row[i] ?? "").filter((cell) => cell.trim());
    const tokens = cells.flatMap(words);
    const longTokens = tokens.filter((token) => length(token) >= 20).length;
    const count = Math.max(1, cells.length);
    const kind: ColumnKind =
      longTokens > 0 && longTokens * 2 >= tokens.length
        ? "token"
        : tokens.length / count >= 4 ||
            cells.reduce((sum, cell) => sum + length(cell), 0) / count >= 28
          ? "narrative"
          : "compact";
    const max = Math.max(3, lineWidth(header), ...cells.map(lineWidth));
    const floor = Math.min(
      max,
      Math.max(
        3,
        kind === "compact"
          ? Math.max(longestToken(header), Math.min(16, Math.max(0, ...cells.map(longestToken))))
          : 16,
      ),
    );
    return { kind, max, floor, priority: kind === "token" ? 0 : kind === "narrative" ? 1 : 2 };
  });
  const budget = Math.max(0, Math.floor(columns) - headers.length * 4 + 2);
  const widths = metrics.map((metric) => metric.max);
  const floors = metrics.map((metric) => metric.floor);
  const shrink = (values: number[], minimums: number[]) => {
    let excess = values.reduce((sum, value) => sum + value, 0) - budget;
    while (excess > 0) {
      let chosen = -1;
      for (let i = 0; i < values.length; i++) {
        if (values[i]! <= minimums[i]!) continue;
        if (
          chosen < 0 ||
          metrics[i]!.priority < metrics[chosen]!.priority ||
          (metrics[i]!.priority === metrics[chosen]!.priority &&
            values[i]! - minimums[i]! > values[chosen]! - minimums[chosen]!)
        )
          chosen = i;
      }
      if (chosen < 0) break;
      values[chosen]!--;
      excess--;
    }
  };
  shrink(
    floors,
    floors.map(() => 3),
  );
  shrink(widths, floors);
  let affected = 0;
  for (const row of rows) {
    const fragmented = metrics.some(
      (metric, i) =>
        (metric.kind === "compact" || (metric.kind === "token" && widths[i]! < 12)) &&
        longestToken(row[i] ?? "") > widths[i]!,
    );
    const expansive = metrics.flatMap((metric, i) =>
      metric.kind === "compact"
        ? []
        : [
            {
              kind: metric.kind,
              width: widths[i]!,
              height: wrappedHeight(row[i] ?? "", widths[i]!),
            },
          ],
    );
    if (
      fragmented ||
      expansive.filter((cell) => cell.height >= 4).length >= 2 ||
      expansive.some((cell) => cell.kind === "narrative" && cell.width < 12 && cell.height >= 7)
    )
      affected++;
  }
  const records =
    rows.length > 0 &&
    (budget < headers.length * 3 ||
      affected >= (rows.length === 1 ? 1 : Math.max(2, Math.ceil(rows.length / 3))));
  const labelWidth = Math.max(0, ...headers.map(lineWidth));
  const minValueWidth = metrics.some((metric) => metric.kind !== "compact") ? 24 : 12;
  return { widths, records, labelWidth, stacked: columns < labelWidth + 3 + minValueWidth };
}

// Ported from T3 Code 40596072 (apps/web/src); see ../T3CODE-LICENSE.
/**
 * GitHub's blockquote alerts: a quote whose first line is `[!NOTE]` — or TIP, IMPORTANT,
 * WARNING, CAUTION — renders as a titled callout. They are GitHub's own extension rather than
 * GFM, so remark-gfm leaves the marker as literal text in the quote. This lifts the marker off
 * the mdast into a `data-alert` attribute for the blockquote renderer to style, and removes
 * the marker line itself.
 *
 * Only a marker with nothing after it on its own line counts, which is GitHub's rule:
 * `> [!NOTE] aside` is an ordinary quote.
 */

interface MarkdownAstNode {
  type?: string;
  value?: unknown;
  data?: {
    hProperties?: Record<string, unknown>;
  };
  children?: MarkdownAstNode[];
}

const GITHUB_ALERT_MARKER = /^\[!(NOTE|TIP|IMPORTANT|WARNING|CAUTION)\](?:\r?\n|$)/i;

function readGithubAlert(node: MarkdownAstNode): void {
  if (node.type !== "blockquote") return;
  const paragraph = node.children?.[0];
  const text = paragraph?.children?.[0];
  if (paragraph?.type !== "paragraph" || text?.type !== "text" || typeof text.value !== "string") {
    return;
  }
  const match = GITHUB_ALERT_MARKER.exec(text.value);
  if (!match?.[1]) return;

  const remainder = text.value.slice(match[0].length);
  // Whether the marker's own line ended inside this text node. Without it, an empty remainder
  // is ambiguous: `[!NOTE]\n**bold**` parses as [text "[!NOTE]\n", strong] — next-line content
  // in a sibling — while `[!NOTE]*aside*` parses the same way minus the newline.
  const markerEndsItsLine = match[0].endsWith("\n");
  if (remainder.length > 0) {
    // The quote continues on the next line inside the same text node: keep the paragraph,
    // shed the marker line.
    text.value = remainder;
  } else if (markerEndsItsLine || paragraph.children?.length === 1) {
    // The marker was the whole text node — a marker-only paragraph, or a marker line whose
    // next line starts as a sibling inline. Drop the node, and the paragraph if it empties.
    paragraph.children?.shift();
    if (paragraph.children?.length === 0) {
      node.children?.shift();
    }
  } else {
    // Something else shares the marker's line — `[!NOTE]*aside*` — which GitHub does not
    // read as an alert.
    return;
  }

  node.data = {
    ...node.data,
    hProperties: {
      ...node.data?.hProperties,
      dataAlert: match[1].toLowerCase(),
    },
  };
}

export function remarkGithubAlerts() {
  return (tree: MarkdownAstNode) => {
    const visit = (node: MarkdownAstNode) => {
      node.children?.forEach(visit);
      readGithubAlert(node);
    };
    visit(tree);
  };
}

// Ported from T3 Code 40596072 (apps/web/src); see ../T3CODE-LICENSE.
import type { Root, RootContent } from "mdast";
import type { Parser as UnifiedParser, Plugin } from "unified";

type Parser = UnifiedParser<Root>;

interface ParsedPrefix {
  source: string;
  offset: number;
  line: number;
  children: RootContent[];
}

function hasDefinitions(node: Root | RootContent): boolean {
  return (
    node.type === "definition" ||
    node.type === "footnoteDefinition" ||
    ("children" in node && node.children.some((child) => hasDefinitions(child)))
  );
}

function shiftPositions(node: Root | RootContent, offset: number, lines: number): void {
  if (node.position) {
    for (const point of [node.position.start, node.position.end]) {
      if (point.offset !== undefined) point.offset += offset;
      point.line += lines;
    }
  }
  if ("children" in node) {
    for (const child of node.children) shiftPositions(child, offset, lines);
  }
}

/** Keep the full document pipeline while avoiding parsing a completed code-heavy
 * prefix on every token. A closed top-level fence followed by a blank line is a
 * parsing boundary. Definitions are document-wide, so they require a full parse.
 */
function createIncrementalMarkdownParser(parse: Parser): Parser {
  let cached: ParsedPrefix | undefined;

  return (source, file) => {
    // A streaming CR can become half of a CRLF. A BOM at the suffix boundary
    // would be stripped by a new parser although it is inside the full document.
    if (source.includes("\r") || source.includes("\uFEFF")) return parse(source, file);

    const prefix = cached && source.startsWith(cached.source) ? cached : undefined;
    let root: Root;
    if (prefix) {
      root = parse(source.slice(prefix.offset), file);
      if (hasDefinitions(root)) return parse(source, file);
      shiftPositions(root, prefix.offset, prefix.line - 1);
      if (root.position) root.position.start = { line: 1, column: 1, offset: 0 };
      // Remark transforms mutate their input. The cache owns pristine nodes and
      // each render receives its own copy, including source positions.
      root.children.unshift(...structuredClone(prefix.children));
    } else {
      root = parse(source, file);
      if (hasDefinitions(root)) return root;
    }

    for (let index = root.children.length - 1; index >= 0; index--) {
      const node = root.children[index];
      if (node?.type !== "code") continue;
      const start = node.position?.start.offset;
      const end = node.position?.end.offset;
      if (start === undefined || end === undefined) continue;
      if (prefix && end < prefix.offset) break;
      const value = source.slice(start, end);
      const opening = /^ {0,3}(`{3,}|~{3,})[^\n]*\n/.exec(value)?.[1];
      if (!opening) continue;
      const lastLine = value.slice(value.lastIndexOf("\n") + 1);
      const closing = new RegExp(`^ {0,3}${opening[0]}{${opening.length},}[ \\t]*$`);
      const separator = /^\n[ \t]*\n/.exec(source.slice(end))?.[0];
      if (!closing.test(lastLine) || !separator) continue;
      const offset = end + separator.length;
      cached = {
        source: source.slice(0, offset),
        offset,
        line: node.position!.end.line + 2,
        children: structuredClone(root.children.slice(0, index + 1)),
      };
      break;
    }
    return root;
  };
}

/** One cache per streaming renderer. Extra syntax plugins must use the normal
 * parser because their document-wide dependencies are not known here.
 */
export function createIncrementalMarkdownPlugin(): Plugin<[], Root> {
  let parser: Parser | undefined;
  return function () {
    const original = this.parser;
    if (!original) return;
    parser ??= createIncrementalMarkdownParser((source, file) => original(source, file) as Root);
    const parseDocument = parser;
    // ReactMarkdown creates a processor per render. Its first parse is the
    // document; transforms can then parse synthetic recovery text on that same
    // processor. Those parses must not read or replace the document's cache.
    let documentParsed = false;
    this.parser = (source, file) => {
      if (documentParsed) return original(source, file);
      documentParsed = true;
      return parseDocument(source, file);
    };
  };
}

// Ported from T3 Code 40596072 (apps/web/src); see ../T3CODE-LICENSE.
interface MarkdownPosition {
  readonly start?: {
    readonly line?: number;
    readonly offset?: number;
  };
}

interface MarkdownAstNode {
  readonly type: string;
  readonly value?: unknown;
  readonly position?: MarkdownPosition;
  children?: MarkdownAstNode[];
}

interface MarkdownFile {
  readonly value?: unknown;
}

interface MarkdownParser {
  parse(markdown: string): unknown;
}

interface RecoveredMarkdown {
  readonly blocks: MarkdownAstNode[];
  readonly source: string;
}

const INLINE_PARSE_PREFIX = "t3-markdown-inline-prefix:";

function isSameLineOverIndentedCode(
  node: MarkdownAstNode,
  parent: MarkdownAstNode | undefined,
  markdown: string,
): boolean {
  if (
    node.type !== "code" ||
    parent?.type !== "listItem" ||
    typeof node.value !== "string" ||
    !/^[\t ]/.test(node.value)
  ) {
    return false;
  }

  const nodeStart = node.position?.start;
  const parentStart = parent.position?.start;
  if (
    nodeStart?.line === undefined ||
    nodeStart.offset === undefined ||
    parentStart?.line === undefined ||
    nodeStart.line !== parentStart.line
  ) {
    return false;
  }

  const sourceCharacter = markdown[nodeStart.offset];
  return sourceCharacter !== "`" && sourceCharacter !== "~";
}

function parseRecoveredMarkdown(value: string, parser: MarkdownParser): RecoveredMarkdown {
  // A text prefix forces block-looking input into a paragraph while preserving
  // the processor's configured inline extensions (for example, GFM syntax).
  // Later root children are kept as blocks so blank-line-separated content is
  // never discarded.
  const source = `${INLINE_PARSE_PREFIX}${value}`;
  const document = parser.parse(source) as MarkdownAstNode;
  const blocks = document.children;
  const paragraph = blocks?.[0];
  const children = paragraph?.type === "paragraph" ? paragraph.children : undefined;
  const first = children?.[0];
  if (
    !blocks ||
    !children ||
    first?.type !== "text" ||
    typeof first.value !== "string" ||
    !first.value.startsWith(INLINE_PARSE_PREFIX)
  ) {
    return { blocks: [{ type: "text", value }], source };
  }

  const firstValue = first.value.slice(INLINE_PARSE_PREFIX.length);
  return {
    blocks: [
      {
        ...paragraph,
        type: "paragraph",
        children: [...(firstValue ? [{ ...first, value: firstValue }] : []), ...children.slice(1)],
      },
      ...blocks.slice(1),
    ],
    source,
  };
}

function blocksFromIndentedCode(node: MarkdownAstNode, parser: MarkdownParser): RecoveredMarkdown {
  const value = typeof node.value === "string" ? node.value.trim() : "";
  const recovered = parseRecoveredMarkdown(value, parser);
  const first = recovered.blocks[0];
  return {
    ...recovered,
    blocks:
      first && node.position
        ? [{ ...first, position: node.position }, ...recovered.blocks.slice(1)]
        : recovered.blocks,
  };
}

/**
 * CommonMark treats four or more spaces after a list marker as an indented
 * code block. In chat output, excessive spacing is commonly accidental
 * alignment such as `-       text`, which otherwise produces a full code card
 * for every bullet. Only normalize blocks that retain excess indentation and
 * start on the marker's own line; explicit fences and conventional indented
 * blocks remain code.
 */
function attachListItemIndentationNormalizer(this: MarkdownParser) {
  return (tree: MarkdownAstNode, file: MarkdownFile) => {
    if (typeof file.value !== "string") {
      return;
    }
    const markdown = file.value;

    const visit = (node: MarkdownAstNode, source: string) => {
      if (!node.children) {
        return;
      }
      node.children = node.children.flatMap((child) => {
        if (isSameLineOverIndentedCode(child, node, source)) {
          const recovered = blocksFromIndentedCode(child, this);
          for (const block of recovered.blocks) {
            visit(block, recovered.source);
          }
          return recovered.blocks;
        }
        visit(child, source);
        return [child];
      });
    };

    visit(tree, markdown);
  };
}

export const remarkNormalizeListItemIndentation = attachListItemIndentationNormalizer;

import { ChatHighlightContext } from '../ChatHighlightLink';
import { highlightReferenceUrl, parseHighlightReference } from '../../../../../domain/mapping/agent-chat/highlightReference';
import { createElement } from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
import Markdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { describe, expect, it } from 'vitest';
import { createIncrementalMarkdownPlugin } from './markdown-incremental';
import { remarkNormalizeListItemIndentation } from './markdown-list-indentation';
import { remarkGithubAlerts } from './markdown-github-alerts';
import { CodexMarkdown } from './CodexMarkdown';
import { codexTableLayout } from './codexTableLayout';

describe('ported t3code markdown', () => {
  it('keeps streaming fences and document-wide references equivalent to a full parse', () => {
    const plugin = createIncrementalMarkdownPlugin();
    const prefix = '# Title\n\n```ts\nconst x = 1;\n```\n\n';
    for (const text of [prefix, `${prefix}**Partial`, `${prefix}**Finished**\n\n[link][ref]\n\n[ref]: https://example.com`, 'Replacement\r\ntext']) {
      const render = (incremental: boolean) => renderToStaticMarkup(createElement(Markdown, { children: text, remarkPlugins: [remarkGfm, ...(incremental ? [plugin] : [])] }));
      expect(render(true)).toBe(render(false));
    }
  });
  it('recovers spaced chat lists while preserving fenced code and GitHub alerts', () => {
    const html = renderToStaticMarkup(createElement(Markdown, { children: '-       **bold**\n\n> [!NOTE]\n> Helpful\n\n```ts\nconst x = 1;\n```', remarkPlugins: [remarkNormalizeListItemIndentation, remarkGithubAlerts] }));
    expect(html).toContain('<strong>bold</strong>');
    expect(html).toContain('data-alert="note"');
    expect(html).toContain('class="language-ts"');
  });
  it('escapes HTML, rejects script URLs and prevents filesystem links navigating the app', () => {
    const html = renderToStaticMarkup(<CodexMarkdown text={'<script>alert(1)</script>\n\n[bad](javascript:alert) [file](/tmp/file.ts) [web](https://example.com)'} />);
    expect(html).not.toContain('<script>'); expect(html).not.toContain('href="javascript:'); expect(html).not.toContain('href="/tmp/');
    expect(html).toContain('rel="noopener noreferrer"'); expect(html).toContain('title="/tmp/file.ts"');
  });
  it('switches narrow tables to labeled records without dropping cells', () => {
    const layout = codexTableLayout(['Feature', 'Description'], [['LongFeatureName', 'A lengthy description that needs space to remain readable.']], 20);
    expect(layout.records).toBe(true); expect(layout.stacked).toBe(true);
    expect(codexTableLayout(['A', 'B'], [['One', 'Two']], 80).records).toBe(false);
  });
});


it('renders saved highlight markers as local navigation buttons and handles malformed destinations safely', () => {
  const target = { documentId: 'doc with spaces', nodeId: 'grid:overview', highlightId: 'highlight-1' };
  const url = highlightReferenceUrl(target);
  expect(parseHighlightReference(url)).toEqual(target);
  const html = renderToStaticMarkup(<ChatHighlightContext.Provider value={() => {}}><CodexMarkdown text={`[Service](${url})`} /></ChatHighlightContext.Provider>);
  expect(html).toContain('agent-highlight-reference');
  expect(html).toContain('Jump to saved highlight');
  expect(html).not.toContain('href=');
  for (const value of ['highlight:%broken/grid:overview/id', 'highlight:doc/grid:overview', 'highlight:doc/not-a-diagram/id', 'javascript:alert(1)']) expect(parseHighlightReference(value)).toBeUndefined();
  const missing = renderToStaticMarkup(<CodexMarkdown text={`[Service](${url})`} />);
  expect(missing).toContain('Highlight reference unavailable');
});

