    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseWheel', ...scrollPoint, deltaX: 0, deltaY: 500 });
    await until('document.querySelector(".diff-hunks-scroll").scrollTop > 300');
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseWheel', ...scrollPoint, deltaX: 0, deltaY: 100000 });
    await until(`document.querySelector('[data-scroll-tracked="true"]')?.getAttribute('aria-label') === 'Removed file'`);
    assert.equal(await read(`document.querySelector('[role=treeitem][aria-selected="true"]')`), null);
    assert.equal(await read('document.querySelector("[data-pane=hunks]").dataset.focused'), 'true');
    await click(node('Detail')); await until(`document.querySelectorAll('.diff-hunk').length === ${discovered.total}`);
    await click('.window-panel button', 'All changes');
    await until(`document.querySelectorAll('.diff-hunk').length === ${discovered.total} && document.querySelector('.diff-hunks-scroll').scrollTop === 0`);
    console.log('Verified complete prefetch, scroll restoration and explorer clearance');
    await click(node('Detail')); await until(`document.querySelectorAll('.diff-hunk').length === ${discovered.total}`);
    await until('document.querySelector("[data-pane=tree]").dataset.focused === "true"');
    await click(`[data-hunk-id="${discovered.hunks.find(h => h.path === 'logic.ts').id}"] button`, 'Copy patch');
    await until('document.querySelector("[data-pane=hunks]").dataset.focused === "true"');
    const canvasState = () => read(`(()=>{const e=document.querySelector('.mapping-viewport > .change-session-preview .diagram-canvas__surface'); const r=e.closest('.mapping-poc-canvas').getBoundingClientRect();return {transform:e.style.transform,width:r.width,height:r.height}})()`);
    const cameraBefore = await canvasState();
    await click('[aria-label="Minimize to focused pane"]');
    await until('!!document.querySelector(".window-panel-minimized") && !document.querySelector(".diff-tree-scroll")');
    assert.ok(await read('Math.abs(document.querySelector(".window-panel").getBoundingClientRect().width / document.querySelector(".mapping-viewport").getBoundingClientRect().width - .4) < .01'));
    assert.deepEqual(await canvasState(), cameraBefore, 'Minimizing changed the canvas camera');
    assert.equal((await hunkPaths()).length, discovered.total);
    const compactScrollPoint = await read(`(()=>{const r=document.querySelector('.diff-hunks-scroll').getBoundingClientRect();return{x:r.x+r.width/2,y:r.y+r.height/2}})()`);
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseWheel', ...compactScrollPoint, deltaX: 0, deltaY: 100000 });
    await until(`(()=>{const e=document.querySelector('.diff-hunks-scroll');return e.scrollTop + e.clientHeight >= e.scrollHeight - 2})()`);
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseWheel', ...compactScrollPoint, deltaX: 0, deltaY: -100000 });
    await until('document.querySelector(".diff-hunks-scroll").scrollTop === 0');
    const edge = await point('[aria-label="Resize window width"]');
    const initialWidth = await read('document.querySelector(".window-panel").getBoundingClientRect().width');
    await cdp.send('Input.dispatchMouseEvent', { type: 'mousePressed', ...edge, button: 'left', buttons: 1, clickCount: 1 });
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: edge.x - 120, y: edge.y, button: 'left', buttons: 1 });
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: edge.x - 120, y: edge.y, button: 'left', buttons: 0, clickCount: 1 });
    await until(`document.querySelector('.window-panel').getBoundingClientRect().width > ${initialWidth + 100}`);
    const resizedWidth = await read('document.querySelector(".window-panel").getBoundingClientRect().width');
    assert.ok(resizedWidth > initialWidth + 100);
    const bottom = await point('[aria-label="Resize window height"]');
    const initialHeight = await read('document.querySelector(".window-panel").getBoundingClientRect().height');
    await cdp.send('Input.dispatchMouseEvent', { type: 'mousePressed', ...bottom, button: 'left', buttons: 1, clickCount: 1 });
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: bottom.x, y: bottom.y - 100, button: 'left', buttons: 1 });
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: bottom.x, y: bottom.y - 100, button: 'left', buttons: 0, clickCount: 1 });
    await until(`document.querySelector('.window-panel').getBoundingClientRect().height < ${initialHeight - 80}`);
    assert.deepEqual(await canvasState(), cameraBefore, 'Resizing changed the canvas camera');
    await click('[aria-label="Restore split view"]');
    assert.deepEqual(await canvasState(), cameraBefore, 'Restoring changed the canvas camera');
    await click('[aria-label="Minimize to focused pane"]');
    assert.equal(await read('document.querySelector(".window-panel").getBoundingClientRect().width'), resizedWidth);
    await click('[aria-label="Restore split view"]');
    console.log('Verified minimized edge resizing, saved width and unchanged canvas camera');
    await click(`[data-hunk-id="${discovered.hunks.find(h => h.path === 'logic.ts').id}"] button`, 'Diagram ↗');
    await until('!!document.querySelector(".window-panel-minimized") && !!document.querySelector(".change-session-preview .is-change-target")');
    await until('!!document.querySelector(".change-inline-coverage")');
    await assertJumpCentered();
    if (process.env.DIFF_TREE_SCREENSHOT) await captureScreenshot(cdp, { output: process.env.DIFF_TREE_SCREENSHOT.replace('.png', '-minimized.png') });
    await assertWorkspaceGeometry();
    await click('[role=tab]', 'Diagrams');
    await until('!!document.querySelector(".window-panel-minimized")');
    await click('[role=tab]', 'Changes');
    await click('[aria-label="Restore split view"]');
    const restoredScrollPoint = await read(`(()=>{const r=document.querySelector('.diff-hunks-scroll').getBoundingClientRect();return{x:r.x+r.width/2,y:r.y+r.height/2}})()`);
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseWheel', ...restoredScrollPoint, deltaX: 0, deltaY: 100000 });
    await until(`document.querySelector('[data-scroll-tracked=true]')?.getAttribute('aria-label') === 'Removed file'`);
    const hunkBeforeTreeJump = await topHunk();
    const trackingBeforeTreeJump = await read(`JSON.parse(sessionStorage.getItem('diff-tree:${id}')).trackedNode`);
    const jumpedNode = await read('document.querySelector(".diff-tree-ascii .diagram-jump").closest(".ascii-line").querySelector("[role=treeitem]").dataset.contentNodeId');
    await click('.diff-tree-ascii .diagram-jump');
    await until('!!document.querySelector(".window-panel-minimized") && !!document.querySelector(".diff-tree-scroll")');
    await assertJumpCentered();
    assert.equal(await read('document.querySelectorAll("[data-scroll-tracked=true]").length'), 0);
    assert.equal(await read(`JSON.parse(sessionStorage.getItem('diff-tree:${id}')).trackedNode`), trackingBeforeTreeJump, 'Minimizing must preserve the saved scroll marker');
    assert.equal(await read('document.querySelector("[role=treeitem][aria-selected=true]").dataset.contentNodeId'), jumpedNode);
    await click('[aria-label="Restore split view"]');
    await until('!!document.querySelector("[data-scroll-tracked=true]")');
    await waitFor(async () => await topHunk() === hunkBeforeTreeJump);
    assert.equal((await hunkPaths()).length, discovered.total);
    assert.equal((await hunkPaths()).filter(p => p === 'logic.ts').length, 2);
    assert.ok(await read('document.querySelector(".diff-hunks-scroll").textContent.includes("captured after")'));
    assert.equal(await read('document.querySelector(".diff-hunks-scroll").textContent.includes("LIVE WORKTREE")'), false);
    assert.deepEqual(await read('[...document.querySelector(".diff-hunk:has(.diff-hunk-code) .diff-hunk-row[data-kind=delete]").querySelectorAll(".diff-hunk-number")].map(e=>e.textContent)'), ['2', '']);
    assert.deepEqual(await read(`[...document.querySelector('[data-hunk-id="${discovered.hunks.find(h => h.path === 'logic.ts').id}"] .diff-hunk-row[data-kind=add]').querySelectorAll('.diff-hunk-number')].map(e=>e.textContent)`), ['', '2']);
    await click(node('Logic'));
    await until('document.querySelectorAll(".diff-hunk-text > span[style]").length > 0');
    await click('.window-panel button', 'Wrap lines'); await waitForSelector(cdp, '.diff-hunk-code.is-wrapped');
    await click(node('Removed file')); await until(`document.querySelectorAll('.diff-hunk').length === ${discovered.total}`);
    assert.ok((await hunkPaths()).includes('removed.txt'));
    assert.ok(await read('document.querySelector(".diff-hunks-scroll").textContent.includes("<captured before>")'));
    await waitForSelector(cdp, '.diff-no-newline');
    await click(node('Unmapped')); await until(`document.querySelectorAll('.diff-hunk').length === ${discovered.total}`);
    await click(node('Logic')); await key('ArrowLeft'); await until('!document.querySelector(\'[role=treeitem][aria-label="Detail"]\')');
    await key('ArrowRight'); await waitForSelector(cdp, node('Detail')); await key('ArrowRight');
    await until('document.activeElement.getAttribute("aria-label") === "Detail"');
    const divider = await point('.window-panel-divider');
    await cdp.send('Input.dispatchMouseEvent', { type: 'mousePressed', ...divider, button: 'left', buttons: 1, clickCount: 1 });
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: divider.x + 80, y: divider.y, button: 'left', buttons: 1 });
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: divider.x + 80, y: divider.y, button: 'left', buttons: 0, clickCount: 1 });
    await until('Number(document.querySelector(".window-panel-divider").getAttribute("aria-valuenow")) > 34');
    await click('.window-panel-divider'); await key('Home'); assert.equal(await read('document.querySelector(".window-panel-divider").getAttribute("aria-valuenow")'), '20');
    await key('ArrowRight');
    if (process.env.DIFF_TREE_SCREENSHOT) await captureScreenshot(cdp, { output: process.env.DIFF_TREE_SCREENSHOT });
    await assertWorkspaceGeometry();
    console.log('Verified captured hunks, highlighting, coordinates, ancestor mapping, folding and pointer/keyboard resize');
    await click(node('Logic')); await key('ArrowLeft');
    await open(docB); await open(docA); await waitForSelector(cdp, node('Logic'));
    assert.equal(await read(`document.querySelector('[role=treeitem][aria-label="Logic"]').getAttribute('aria-expanded')`), 'false');
    await click(node('Logic')); await key('ArrowRight');
    await layout('full-single'); await click('[role=tab]', 'Change tree'); await click(node('Removed file'));
    await until('document.querySelector(\'[role=tab][aria-selected="true"]\')?.textContent === "Hunks"');
    await until('document.querySelector(".diff-hunks-scroll").scrollTop > 0');
    await layout('split-single'); await waitForSelector(cdp, '.window-panel-canvas .diagram-content-node');
    assert.ok(await read('document.querySelector(".window-panel-canvas").getBoundingClientRect().right <= document.querySelector(".window-panel-content").getBoundingClientRect().left + 1'));
    const canvasPoint = await point('.window-panel-canvas .mapping-poc-canvas');
    await cdp.send('Input.dispatchMouseEvent', { type: 'mousePressed', ...canvasPoint, button: 'middle', buttons: 4, clickCount: 1 });
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: canvasPoint.x + 60, y: canvasPoint.y + 30, button: 'middle', buttons: 4 });
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: canvasPoint.x + 60, y: canvasPoint.y + 30, button: 'middle', buttons: 0, clickCount: 1 });
    const compactCamera = await read('document.querySelector(".window-panel-canvas .diagram-canvas__surface").style.transform');
    await click('[aria-label="Minimize to focused pane"]');
    await click('[aria-label="Restore split view"]');
    assert.equal(await read('document.querySelector(".window-panel-canvas .diagram-canvas__surface").style.transform'), compactCamera, 'Minimize/restore reset the beside-canvas camera');

    if (process.env.DIFF_TREE_SCREENSHOT) await captureScreenshot(cdp, { output: process.env.DIFF_TREE_SCREENSHOT.replace('.png', '-split.png') });
    await open(docB); await waitForSelector(cdp, '.window-panel-split-single'); await open(docA); await waitForSelector(cdp, '.window-panel-split-single');
    await until('document.querySelector(".diff-hunks-scroll").scrollTop > 0');
    await click('[aria-label="Close Captured review · DiffTree"]'); await until('!document.querySelector(".window-panel")');
    await click('.change-session-actions button', 'Diff tree'); await waitForSelector(cdp, '.window-panel-split-single');
    await click('[role=tab]', 'Diagrams'); await until('!!document.querySelector(".window-panel")');
    await click('[role=tab]', 'Changes'); await click(`[data-change-session-summary="${id}"]`); await open(docA); await waitForSelector(cdp, '.window-panel-split-single');
    const origin = await read('performance.timeOrigin'); await cdp.send('Page.reload'); await waitFor(async () => await read('performance.timeOrigin').catch(() => origin) !== origin);
    await waitForSelector(cdp, '[role=tab]'); await click('[role=tab]', 'Changes'); await click(`[data-change-session-summary="${id}"]`); await open(docA); await waitForSelector(cdp, '.window-panel-split-single');
    await until('document.querySelector(".diff-hunks-scroll")?.scrollTop > 0');
    console.log('Verified all layouts, review state across canvases, close/navigation and restored state after reload');
    // Agent-side updates are external inputs, not simulated UI edits.
    const result = await fetch(`${url}/api/mapping/agent/tools/update_diagram_change_session`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ changeSessionId: id, expectedVersion: fixtureVersion, requestId: 'new-tree', diffTree: { expectedRevisionId: proposal.diffTree.revisionId, ascii: 'Updated tree\n`-- Nothing mapped', mappings: [] } }) });
    assert.equal(result.ok, true, await result.text());
    await layout('full-split'); await until('document.querySelector(".diff-tree-ascii")?.textContent.includes("Updated tree")');
    await until(`document.querySelectorAll('.diff-hunk').length === ${discovered.total}`);
    await click(node('Nothing mapped')); await until(`document.querySelectorAll('.diff-hunk').length === ${discovered.total}`);
    await click(`[data-change-session-summary="${emptyProposal.changeSessionId}"]`);
    await click(`[data-open-difftree="${emptyProposal.changeSessionId}"]`);
    await until('document.querySelector(".diff-hunks-scroll")?.textContent.includes("No captured hunks in this session.")');
    await waitForSelector(cdp, node('No captured hunks'));
    assert.deepEqual(errors, []);
  });
  console.log('PASS: DiffTree WindowPanel browser checks, including live mapping updates.');
} finally {
  if (server && server.exitCode === null) { server.kill('SIGTERM'); await new Promise(resolve => server.once('exit', resolve)); }
  await rm(root, { recursive: true, force: true });
}

